public class StringIntroductionDemo {
    public static void main(String[] args) {
        // String literal declaration
        String greeting = "Welcome to LearnBySelf!";
        String language = "Java";

        // Outputting string content
        System.out.println("Greeting: " + greeting);
        System.out.println("Language: " + language);

        // Invoking String instance methods
        int greetingLength = greeting.length();
        char firstLetter = language.charAt(0);
        char lastLetter = language.charAt(language.length() - 1);

        System.out.println("Total characters in greeting: " + greetingLength);
        System.out.println("First letter of language: " + firstLetter);
        System.out.println("Last letter of language: " + lastLetter);

        // Demonstrating that String holds references, not primitive values
        String copyRef = language;
        System.out.println("copyRef points to: " + copyRef);
    }
}

