practiceProblems.solutionCode:
public class MiddleCharExtractor {
    public static void main(String[] args) {
        String word = "Learn";
        int midIndex = word.length() / 2;
        char midChar = word.charAt(midIndex);
        System.out.println("Middle Index: " + midIndex);
        System.out.println("Middle Character: " + midChar);
    }
}

